import { z } from "zod";

const idSchema = z
	.string()
	.min(2)
	.max(96)
	.regex(/^[A-Za-z0-9][A-Za-z0-9_-]*$/, "Use letters, numbers, dashes, or underscores");
const isoDateSchema = z.string().datetime({ offset: true });
const shortTextSchema = z.string().trim().min(1).max(240);
const bodyTextSchema = z.string().max(120_000);

export const courseRoleSchema = z.enum(["owner", "teacher", "student", "peer"]);
export type CourseRole = z.infer<typeof courseRoleSchema>;

export const teacherAccessSchema = z.enum(["private", "requested", "full"]);
export type TeacherAccess = z.infer<typeof teacherAccessSchema>;

export const courseMaterialSchema = z.object({
	id: idSchema,
	kind: z.enum(["document", "link", "note", "anki"]),
	title: shortTextSchema,
	description: z.string().trim().max(2_000).optional(),
	url: z.string().url().max(4_096).optional(),
	storageKey: z.string().max(512).optional(),
	fileName: z.string().trim().max(255).optional(),
	mimeType: z.string().trim().max(160).optional(),
	sizeBytes: z.number().int().nonnegative().max(25 * 1024 * 1024).optional(),
	createdAt: isoDateSchema,
	createdBy: z.string().min(1).max(256),
});
export type CourseMaterial = z.infer<typeof courseMaterialSchema>;

export const courseCardSchema = z.object({
	id: idSchema,
	front: z.string().trim().min(1).max(10_000),
	back: z.string().trim().min(1).max(20_000),
	tags: z.array(z.string().trim().min(1).max(64)).max(24).default([]),
	lessonId: idSchema.optional(),
	updatedAt: isoDateSchema,
	updatedBy: z.string().min(1).max(256),
});
export type CourseCard = z.infer<typeof courseCardSchema>;

export const courseExerciseSchema = z.object({
	id: idSchema,
	prompt: z.string().trim().min(1).max(30_000),
	placeholder: z.string().trim().max(240).optional(),
	rubric: z.array(z.string().trim().min(1).max(1_000)).max(12).default([]),
});
export type CourseExercise = z.infer<typeof courseExerciseSchema>;

export const courseLessonSchema = z.object({
	id: idSchema,
	title: shortTextSchema,
	summary: z.string().trim().max(2_000).default(""),
	estimatedMinutes: z.number().int().positive().max(1_440).optional(),
	objectives: z.array(z.string().trim().min(1).max(1_000)).max(16).default([]),
	reading: bodyTextSchema.default(""),
	exercise: courseExerciseSchema.optional(),
	materialIds: z.array(idSchema).max(64).default([]),
	cardIds: z.array(idSchema).max(500).default([]),
});
export type CourseLesson = z.infer<typeof courseLessonSchema>;

export const courseModuleSchema = z.object({
	id: idSchema,
	title: shortTextSchema,
	description: z.string().trim().max(2_000).default(""),
	lessons: z.array(courseLessonSchema).max(64).default([]),
});
export type CourseModule = z.infer<typeof courseModuleSchema>;

export const courseProgressSchema = z.object({
	activeLessonId: idSchema.optional(),
	completedLessonIds: z.array(idSchema).max(2_000).default([]),
	lastActiveAt: isoDateSchema,
});
export type CourseProgress = z.infer<typeof courseProgressSchema>;

export const courseMemberSchema = z.object({
	accountId: z.string().min(1).max(256),
	displayName: z.string().trim().min(1).max(120),
	role: courseRoleSchema,
	teacherAccess: teacherAccessSchema.default("private"),
	joinedAt: isoDateSchema,
	progress: courseProgressSchema,
});
export type CourseMember = z.infer<typeof courseMemberSchema>;

export const courseSharedNoteSchema = z.object({
	id: idSchema,
	lessonId: idSchema,
	title: z.string().trim().min(1).max(160),
	text: bodyTextSchema,
	version: z.number().int().nonnegative(),
	updatedAt: isoDateSchema,
	updatedBy: z.string().min(1).max(256),
});
export type CourseSharedNote = z.infer<typeof courseSharedNoteSchema>;

export const courseSubmissionSchema = z.object({
	id: idSchema,
	lessonId: idSchema,
	exerciseId: idSchema,
	accountId: z.string().min(1).max(256),
	answer: bodyTextSchema,
	sharedWithPeers: z.boolean().default(false),
	version: z.number().int().positive(),
	updatedAt: isoDateSchema,
	review: z
		.object({
			status: z.enum(["needs-review", "reviewed"]),
			feedback: z.string().max(30_000).default(""),
			reviewerAccountId: z.string().min(1).max(256),
			updatedAt: isoDateSchema,
		})
		.optional(),
});
export type CourseSubmission = z.infer<typeof courseSubmissionSchema>;

export const courseCommentSchema = z.object({
	id: idSchema,
	lessonId: idSchema,
	accountId: z.string().min(1).max(256),
	body: z.string().trim().min(1).max(12_000),
	createdAt: isoDateSchema,
});
export type CourseComment = z.infer<typeof courseCommentSchema>;

export const courseActivitySchema = z.object({
	id: idSchema,
	type: z.enum([
		"course-created",
		"lesson-completed",
		"note-updated",
		"submission-saved",
		"submission-reviewed",
		"comment-added",
		"card-updated",
		"material-added",
		"teacher-access-requested",
		"teacher-access-changed",
		"member-joined",
		"member-role-changed",
	]),
	accountId: z.string().min(1).max(256),
	message: z.string().trim().min(1).max(500),
	lessonId: idSchema.optional(),
	createdAt: isoDateSchema,
});
export type CourseActivity = z.infer<typeof courseActivitySchema>;

export const courseSettingsSchema = z.object({
	teacherAccessPolicy: z.enum(["request", "required-on-enrollment"]).default("request"),
	allowPeerDeckEdits: z.boolean().default(true),
	allowPeerComments: z.boolean().default(true),
});
export type CourseSettings = z.infer<typeof courseSettingsSchema>;

export const courseSchema = z.object({
	schemaVersion: z.literal(1),
	id: idSchema,
	title: shortTextSchema,
	description: z.string().trim().max(4_000).default(""),
	outcomes: z.array(z.string().trim().min(1).max(1_000)).max(24).default([]),
	ownerAccountId: z.string().min(1).max(256),
	createdAt: isoDateSchema,
	updatedAt: isoDateSchema,
	revision: z.number().int().nonnegative(),
	modules: z.array(courseModuleSchema).max(48).default([]),
	materials: z.array(courseMaterialSchema).max(500).default([]),
	cards: z.array(courseCardSchema).max(10_000).default([]),
	members: z.array(courseMemberSchema).min(1).max(5_000),
	sharedNotes: z.array(courseSharedNoteSchema).max(2_000).default([]),
	submissions: z.array(courseSubmissionSchema).max(50_000).default([]),
	comments: z.array(courseCommentSchema).max(50_000).default([]),
	activity: z.array(courseActivitySchema).max(5_000).default([]),
	settings: courseSettingsSchema,
});
export type Course = z.infer<typeof courseSchema>;

export const courseCreateInputSchema = z.object({
	title: shortTextSchema,
	description: z.string().trim().max(4_000).default(""),
	outcomes: z.array(z.string().trim().min(1).max(1_000)).max(24).default([]),
	modules: z.array(courseModuleSchema).max(48).default([]),
	settings: courseSettingsSchema.partial().optional(),
});
export type CourseCreateInput = z.infer<typeof courseCreateInputSchema>;

export const courseInviteSchema = z.object({
	id: idSchema,
	courseId: idSchema,
	role: z.enum(["teacher", "student", "peer"]),
	createdBy: z.string().min(1).max(256),
	createdAt: isoDateSchema,
	expiresAt: isoDateSchema,
	maxUses: z.number().int().positive().max(5_000),
	uses: z.number().int().nonnegative(),
	tokenHash: z.string().length(64),
});
export type CourseInvite = z.infer<typeof courseInviteSchema>;

const operationBaseSchema = z.object({
	id: idSchema,
	courseId: idSchema,
	baseRevision: z.number().int().nonnegative(),
});

export const courseOperationSchema = z.discriminatedUnion("type", [
	operationBaseSchema.extend({
		type: z.literal("course.update"),
		patch: z.object({
			title: shortTextSchema.optional(),
			description: z.string().trim().max(4_000).optional(),
			outcomes: z.array(z.string().trim().min(1).max(1_000)).max(24).optional(),
		}),
	}),
	operationBaseSchema.extend({
		type: z.literal("lesson.update"),
		moduleId: idSchema,
		lesson: courseLessonSchema,
	}),
	operationBaseSchema.extend({
		type: z.literal("lesson.complete"),
		lessonId: idSchema,
		completed: z.boolean(),
	}),
	operationBaseSchema.extend({
		type: z.literal("shared-note.update"),
		noteId: idSchema,
		lessonId: idSchema,
		title: z.string().trim().min(1).max(160),
		text: bodyTextSchema,
		baseVersion: z.number().int().nonnegative(),
	}),
	operationBaseSchema.extend({
		type: z.literal("submission.save"),
		submissionId: idSchema,
		lessonId: idSchema,
		exerciseId: idSchema,
		answer: bodyTextSchema,
		sharedWithPeers: z.boolean().default(false),
	}),
	operationBaseSchema.extend({
		type: z.literal("submission.review"),
		submissionId: idSchema,
		status: z.enum(["needs-review", "reviewed"]),
		feedback: z.string().max(30_000).default(""),
	}),
	operationBaseSchema.extend({
		type: z.literal("comment.add"),
		commentId: idSchema,
		lessonId: idSchema,
		body: z.string().trim().min(1).max(12_000),
	}),
	operationBaseSchema.extend({
		type: z.literal("card.upsert"),
		card: courseCardSchema.omit({ updatedAt: true, updatedBy: true }),
	}),
	operationBaseSchema.extend({
		type: z.literal("material.add"),
		material: courseMaterialSchema.omit({ createdAt: true, createdBy: true }),
	}),
	operationBaseSchema.extend({
		type: z.literal("teacher-access.request"),
		memberAccountId: z.string().min(1).max(256),
	}),
	operationBaseSchema.extend({
		type: z.literal("teacher-access.respond"),
		approve: z.boolean(),
	}),
	operationBaseSchema.extend({
		type: z.literal("member.role.update"),
		memberAccountId: z.string().min(1).max(256),
		role: z.enum(["teacher", "student", "peer"]),
	}),
]);
export type CourseOperation = z.infer<typeof courseOperationSchema>;

export interface CoursePermissions {
	canEditCourse: boolean;
	canInvite: boolean;
	canReview: boolean;
	canEditDeck: boolean;
	canRequestTeacherAccess: boolean;
}

export interface CourseViewerSnapshot {
	course: Course;
	viewer: CourseMember;
	permissions: CoursePermissions;
}

export interface CourseListItem {
	id: string;
	title: string;
	description: string;
	role: CourseRole;
	memberCount: number;
	lessonCount: number;
	completedLessons: number;
	updatedAt: string;
}

export type CourseRealtimeMessage =
	| { type: "snapshot"; snapshot: CourseViewerSnapshot }
	| { type: "course.updated"; courseId: string; revision: number }
	| { type: "presence"; courseId: string; accountIds: string[] }
	| { type: "gateway.status"; status: "connected" | "reconnecting" | "offline" }
	| { type: "error"; message: string; code?: string };

export function allCourseLessons(course: Pick<Course, "modules">): CourseLesson[] {
	return course.modules.flatMap((module) => module.lessons);
}

export function courseCompletionPercent(course: Course, member: CourseMember): number {
	const lessonCount = allCourseLessons(course).length;
	if (lessonCount === 0) return 0;
	const knownLessonIds = new Set(allCourseLessons(course).map((lesson) => lesson.id));
	const completed = new Set(
		member.progress.completedLessonIds.filter((lessonId) => knownLessonIds.has(lessonId)),
	).size;
	return Math.round((completed / lessonCount) * 100);
}
import {
	allCourseLessons,
	type Course,
	type CourseActivity,
	type CourseMember,
	type CourseOperation,
	type CoursePermissions,
	type CourseRole,
	type CourseSubmission,
	type CourseViewerSnapshot,
} from "./contracts";

export class CourseAuthorizationError extends Error {
	readonly code = "course_forbidden";
}

export class CourseConflictError extends Error {
	readonly code = "course_conflict";
	constructor(
		message: string,
		readonly currentRevision: number,
	) {
		super(message);
	}
}

export class CourseNotFoundError extends Error {
	readonly code = "course_not_found";
}

function memberFor(course: Course, accountId: string): CourseMember {
	const member = course.members.find((candidate) => candidate.accountId === accountId);
	if (!member) throw new CourseAuthorizationError("You are not enrolled in this course.");
	return member;
}

function roleCanTeach(role: CourseRole): boolean {
	return role === "owner" || role === "teacher";
}

function roleCanOwn(role: CourseRole): boolean {
	return role === "owner";
}

function assertLesson(course: Course, lessonId: string): void {
	if (!allCourseLessons(course).some((lesson) => lesson.id === lessonId)) {
		throw new CourseNotFoundError("This lesson is no longer part of the course.");
	}
}

function activity(
	type: CourseActivity["type"],
	accountId: string,
	message: string,
	createdAt: string,
	lessonId?: string,
): CourseActivity {
	return {
		id: `activity_${crypto.randomUUID().replaceAll("-", "")}`,
		type,
		accountId,
		message,
		createdAt,
		...(lessonId ? { lessonId } : {}),
	};
}

function appendActivity(course: Course, item: CourseActivity): void {
	course.activity = [item, ...course.activity].slice(0, 5_000);
}

function operationNeedsCurrentRevision(operation: CourseOperation): boolean {
	return (
		operation.type === "course.update" ||
		operation.type === "lesson.update" ||
		operation.type === "material.add" ||
		operation.type === "member.role.update"
	);
}

export function permissionsFor(course: Course, accountId: string): CoursePermissions {
	const member = memberFor(course, accountId);
	const canTeach = roleCanTeach(member.role);
	return {
		canEditCourse: canTeach,
		canInvite: canTeach,
		canReview: canTeach,
		canEditDeck: canTeach || course.settings.allowPeerDeckEdits,
		canRequestTeacherAccess: canTeach,
	};
}

export function applyCourseOperation(
	current: Course,
	actorAccountId: string,
	operation: CourseOperation,
	now = new Date().toISOString(),
): Course {
	if (operation.courseId !== current.id) {
		throw new CourseNotFoundError("The operation targets a different course.");
	}
	if (operationNeedsCurrentRevision(operation) && operation.baseRevision !== current.revision) {
		throw new CourseConflictError(
			"The course changed while you were editing. Refresh and try again.",
			current.revision,
		);
	}

	const actor = memberFor(current, actorAccountId);
	const next = structuredClone(current);

	switch (operation.type) {
		case "course.update": {
			if (!roleCanTeach(actor.role)) {
				throw new CourseAuthorizationError("Only course teachers can change course details.");
			}
			Object.assign(next, operation.patch);
			break;
		}
		case "lesson.update": {
			if (!roleCanTeach(actor.role)) {
				throw new CourseAuthorizationError("Only course teachers can edit lessons.");
			}
			const module = next.modules.find((candidate) => candidate.id === operation.moduleId);
			if (!module) throw new CourseNotFoundError("This module is no longer part of the course.");
			const index = module.lessons.findIndex((lesson) => lesson.id === operation.lesson.id);
			if (index === -1) module.lessons.push(operation.lesson);
			else module.lessons[index] = operation.lesson;
			break;
		}
		case "lesson.complete": {
			assertLesson(next, operation.lessonId);
			const target = next.members.find((member) => member.accountId === actorAccountId)!;
			const completed = new Set(target.progress.completedLessonIds);
			if (operation.completed) completed.add(operation.lessonId);
			else completed.delete(operation.lessonId);
			target.progress.completedLessonIds = [...completed];
			target.progress.activeLessonId = operation.lessonId;
			target.progress.lastActiveAt = now;
			appendActivity(
				next,
				activity(
					"lesson-completed",
					actorAccountId,
					operation.completed ? "Completed a lesson" : "Reopened a lesson",
					now,
					operation.lessonId,
				),
			);
			break;
		}
		case "shared-note.update": {
			assertLesson(next, operation.lessonId);
			const index = next.sharedNotes.findIndex((note) => note.id === operation.noteId);
			const existing = index === -1 ? null : next.sharedNotes[index];
			if (existing && existing.version !== operation.baseVersion) {
				throw new CourseConflictError(
					"Someone else changed these shared notes. Review their version before saving yours.",
					next.revision,
				);
			}
			const note = {
				id: operation.noteId,
				lessonId: operation.lessonId,
				title: operation.title,
				text: operation.text,
				version: (existing?.version ?? 0) + 1,
				updatedAt: now,
				updatedBy: actorAccountId,
			};
			if (index === -1) next.sharedNotes.push(note);
			else next.sharedNotes[index] = note;
			appendActivity(next, activity("note-updated", actorAccountId, "Updated shared notes", now, operation.lessonId));
			break;
		}
		case "submission.save": {
			assertLesson(next, operation.lessonId);
			const index = next.submissions.findIndex(
				(submission) =>
					submission.id === operation.submissionId && submission.accountId === actorAccountId,
			);
			const existing = index === -1 ? null : next.submissions[index];
			const submission: CourseSubmission = {
				id: operation.submissionId,
				lessonId: operation.lessonId,
				exerciseId: operation.exerciseId,
				accountId: actorAccountId,
				answer: operation.answer,
				sharedWithPeers: operation.sharedWithPeers,
				version: (existing?.version ?? 0) + 1,
				updatedAt: now,
				...(existing?.review ? { review: existing.review } : {}),
			};
			if (index === -1) next.submissions.push(submission);
			else next.submissions[index] = submission;
			appendActivity(next, activity("submission-saved", actorAccountId, "Saved exercise work", now, operation.lessonId));
			break;
		}
		case "submission.review": {
			if (!roleCanTeach(actor.role)) {
				throw new CourseAuthorizationError("Only course teachers can review submissions.");
			}
			const submission = next.submissions.find((candidate) => candidate.id === operation.submissionId);
			if (!submission) throw new CourseNotFoundError("This submission could not be found.");
			const student = memberFor(next, submission.accountId);
			if (student.teacherAccess !== "full") {
				throw new CourseAuthorizationError("The learner has not granted full teacher access.");
			}
			submission.review = {
				status: operation.status,
				feedback: operation.feedback,
				reviewerAccountId: actorAccountId,
				updatedAt: now,
			};
			appendActivity(next, activity("submission-reviewed", actorAccountId, "Reviewed exercise work", now, submission.lessonId));
			break;
		}
		case "comment.add": {
			if (!next.settings.allowPeerComments && !roleCanTeach(actor.role)) {
				throw new CourseAuthorizationError("Peer comments are disabled for this course.");
			}
			assertLesson(next, operation.lessonId);
			next.comments.push({
				id: operation.commentId,
				lessonId: operation.lessonId,
				accountId: actorAccountId,
				body: operation.body,
				createdAt: now,
			});
			appendActivity(next, activity("comment-added", actorAccountId, "Added a lesson comment", now, operation.lessonId));
			break;
		}
		case "card.upsert": {
			if (!roleCanTeach(actor.role) && !next.settings.allowPeerDeckEdits) {
				throw new CourseAuthorizationError("Only course teachers can edit this deck.");
			}
			const index = next.cards.findIndex((card) => card.id === operation.card.id);
			const card = { ...operation.card, updatedAt: now, updatedBy: actorAccountId };
			if (index === -1) next.cards.push(card);
			else next.cards[index] = card;
			appendActivity(next, activity("card-updated", actorAccountId, "Updated an Anki card", now, card.lessonId));
			break;
		}
		case "material.add": {
			if (!roleCanTeach(actor.role)) {
				throw new CourseAuthorizationError("Only course teachers can add course materials.");
			}
			const material = { ...operation.material, createdAt: now, createdBy: actorAccountId };
			const index = next.materials.findIndex((candidate) => candidate.id === material.id);
			if (index === -1) next.materials.push(material);
			else next.materials[index] = material;
			appendActivity(next, activity("material-added", actorAccountId, "Added course material", now));
			break;
		}
		case "teacher-access.request": {
			if (!roleCanTeach(actor.role)) {
				throw new CourseAuthorizationError("Only course teachers can request full access.");
			}
			const target = memberFor(next, operation.memberAccountId);
			if (roleCanTeach(target.role)) {
				throw new CourseAuthorizationError("Teacher access applies to learners and invited peers.");
			}
			target.teacherAccess = "requested";
			appendActivity(next, activity("teacher-access-requested", actorAccountId, "Requested full teacher access", now));
			break;
		}
		case "teacher-access.respond": {
			const target = memberFor(next, actorAccountId);
			if (target.teacherAccess !== "requested") {
				throw new CourseConflictError("There is no active teacher-access request.", next.revision);
			}
			target.teacherAccess = operation.approve ? "full" : "private";
			appendActivity(
				next,
				activity(
					"teacher-access-changed",
					actorAccountId,
					operation.approve ? "Granted full teacher access" : "Declined full teacher access",
					now,
				),
			);
			break;
		}
		case "member.role.update": {
			if (!roleCanOwn(actor.role)) {
				throw new CourseAuthorizationError("Only the course owner can change member roles.");
			}
			const target = memberFor(next, operation.memberAccountId);
			if (target.role === "owner") {
				throw new CourseAuthorizationError("Transfer ownership before changing the owner role.");
			}
			target.role = operation.role;
			appendActivity(next, activity("member-role-changed", actorAccountId, "Changed a course member role", now));
			break;
		}
	}

	next.revision += 1;
	next.updatedAt = now;
	return next;
}

function canSeeSubmission(course: Course, viewer: CourseMember, submission: CourseSubmission): boolean {
	if (submission.accountId === viewer.accountId) return true;
	if (roleCanTeach(viewer.role)) {
		return memberFor(course, submission.accountId).teacherAccess === "full";
	}
	return submission.sharedWithPeers;
}

export function projectCourseForViewer(course: Course, viewerAccountId: string): CourseViewerSnapshot {
	const viewer = memberFor(course, viewerAccountId);
	const projected = structuredClone(course);
	projected.submissions = projected.submissions.filter((submission) =>
		canSeeSubmission(course, viewer, submission),
	);
	return {
		course: projected,
		viewer: structuredClone(viewer),
		permissions: permissionsFor(course, viewerAccountId),
	};
}
